package com.mavric.health.persistence.sqlserver;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.shared.ApiException;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Real REQUIRED templates, modeled manager/executor; no SQL Server or DB principal authentication. */
class SqlServerBootstrapStoreTest {
 static final String ID="aa000000-0000-4000-8000-000000000001";
 final SqlServerExecutor executor=mock(SqlServerExecutor.class);final ModelTransactionManager manager=new ModelTransactionManager();final SqlServerBootstrapStore store=new SqlServerBootstrapStore(executor,manager);final Deque<SqlServerExecutor.Result> results=new ArrayDeque<>();final List<SqlServerProcedure> calls=new ArrayList<>();final List<List<Object>> args=new ArrayList<>();
 SqlServerBootstrapStoreTest(){when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());assertEquals(new SqlServerContext(null,null,null,null,null,null,null,null,null,SqlServerContext.Scope.BOOTSTRAP),inv.getArgument(1));calls.add(inv.getArgument(0));args.add(Arrays.asList(((Object[])inv.getRawArguments()[2]).clone()));return results.removeFirst();});}
 void rows(List<Map<String,Object>> rows){results.add(new SqlServerExecutor.Result(List.of(rows),List.of(0)));}
 void create(){rows(List.of());results.add(new SqlServerExecutor.Result(List.of(),List.of(0)));}
 @AfterEach void cleanup(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 static void safe(Runnable work){var e=assertThrows(ApiException.class,work::run);assertEquals(500,e.status);assertEquals("DATABASE_ERROR",e.code);assertNull(e.getCause());assertFalse(e.toString().contains("canary"));}
 @Test void createUsesExactDescriptorsLazySupplierAndServerUuidRootCaseWithoutTrim(){create();var count=new AtomicInteger();store.initialize(" QA+I@EXAMPLE.TEST ",()->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());count.incrementAndGet();return "encoded-only";});assertEquals(1,count.get());assertEquals(List.of(SqlServerProcedure.BOOTSTRAP_EXISTS,SqlServerProcedure.BOOTSTRAP_CREATE),calls);assertEquals(List.of(),args.getFirst());var values=args.getLast();assertEquals(3,values.size());assertEquals(values.getFirst(),UUID.fromString((String)values.getFirst()).toString());assertEquals(" qa+i@example.test ",values.get(1));assertEquals("encoded-only",values.get(2));assertEquals(List.of("begin:0","commit"),manager.events);assertEquals("SqlServerBootstrapStore[redacted]",store.toString());}
 @Test void existingAdminSkipsAllAdditionalConfigurationAndSupplier(){rows(List.of(Map.of("id",ID)));store.initialize(null,null);rows(List.of(Map.of("id",ID)));store.initialize("x".repeat(255),()->{fail("supplier must not run");return null;});assertEquals(Collections.nCopies(2,SqlServerProcedure.BOOTSTRAP_EXISTS),calls);}
 @Test void malformedExistsCardinalityTypesUuidAndExtraRsRollback(){for(var row:List.<Map<String,Object>>of(Map.of(),Map.of("id",1),Map.of("id","bad"),Map.of("id",ID.toUpperCase(Locale.ROOT)))){rows(List.of(row));safe(()->store.initialize("qa@example.test",()->"hash"));assertEquals("rollback",manager.events.getLast());}rows(List.of(Map.of("id",ID),Map.of("id",ID)));safe(()->store.initialize("qa@example.test",()->"hash"));for(var sets:List.<List<List<Map<String,Object>>>>of(List.of(),List.of(List.of(),List.of()))){results.add(new SqlServerExecutor.Result(sets,List.of()));safe(()->store.initialize("qa@example.test",()->"hash"));}assertFalse(calls.contains(SqlServerProcedure.BOOTSTRAP_CREATE));}
 @Test void inputLimitsAndNullSupplierValidatedOnlyWhenMissingAdmin(){for(String email:Arrays.asList(null," ","x".repeat(255))){rows(List.of());assertEquals(400,assertThrows(ApiException.class,()->store.initialize(email,()->{fail("invalid email must not hash");return "hash";})).status);}rows(List.of());safe(()->store.initialize("qa@example.test",null));for(String hash:Arrays.asList(null," ","x".repeat(101))){rows(List.of());assertEquals(400,assertThrows(ApiException.class,()->store.initialize("qa@example.test",()->hash)).status);}create();store.initialize("a".repeat(241)+"@example.test",()->"h".repeat(100));assertEquals(254,((String)args.getLast().get(1)).length());assertEquals(100,((String)args.getLast().get(2)).length());}
 @Test void supplierWriteAndCommitErrorsDoNotReturnSuccessOrRetry(){rows(List.of());safe(()->store.initialize("qa@example.test",()->{throw new RuntimeException("canary encode");}));rows(List.of());rows(List.of());safe(()->store.initialize("qa@example.test",()->"hash"));create();manager.failCommit=true;safe(()->store.initialize("qa@example.test",()->"hash"));doThrow(new RuntimeException(new java.sql.SQLException("canary driver",null,51003))).when(executor).execute(any(),any(),any(Object[].class));assertEquals(409,assertThrows(ApiException.class,()->store.initialize("qa@example.test",()->"hash")).status);verify(executor,times(6)).execute(any(),any(),any(Object[].class));}
 @Test void joinsOuterAndPreservesCallerContextAndFatalError(){var request=new MockHttpServletRequest("POST","/forged");TraceContext.REQUEST.set(request);var auth=new org.springframework.security.authentication.UsernamePasswordAuthenticationToken("forged",null);SecurityContextHolder.getContext().setAuthentication(auth);create();assertThrows(RuntimeException.class,()->manager.outer(()->{store.initialize("qa@example.test",()->"hash");assertEquals(List.of("begin:0"),manager.events);throw new RuntimeException("synthetic cancel");}));assertEquals("rollback",manager.events.getLast());assertSame(request,TraceContext.REQUEST.get());assertSame(auth,SecurityContextHolder.getContext().getAuthentication());rows(List.of());var error=new AssertionError("synthetic fatal");assertSame(error,assertThrows(AssertionError.class,()->store.initialize("qa@example.test",()->{throw error;})));}
 @Test void realExecutorRuntimePurposeCannotReachJdbcForBootstrap(){var jdbc=mock(org.springframework.jdbc.core.JdbcTemplate.class);var runtime=new SqlServerExecutor(jdbc,new tools.jackson.databind.ObjectMapper(),SqlServerExecutor.Purpose.RUNTIME);var wrong=new SqlServerBootstrapStore(runtime,manager);assertEquals(400,assertThrows(ApiException.class,()->wrong.initialize("qa@example.test",()->"hash")).status);verifyNoInteractions(jdbc);}
 @Test void createVendorFailureRollsBackAfterSingleExistsAndDoesNotRetry(){doAnswer(inv->{if(inv.getArgument(0)==SqlServerProcedure.BOOTSTRAP_EXISTS)return new SqlServerExecutor.Result(List.of(List.of()),List.of());throw new RuntimeException(new java.sql.SQLException("canary CREATE",null,51001));}).when(executor).execute(any(),any(),any(Object[].class));var error=assertThrows(ApiException.class,()->store.initialize("qa@example.test",()->"encoded"));assertEquals(403,error.status);assertFalse(error.toString().contains("canary"));assertEquals("rollback",manager.events.getLast());verify(executor,times(2)).execute(any(),any(),any(Object[].class));}

}
